  if (!Bun.file(filePath).size) return { tasks: [], nextId: 1 };
  try {
    return validateDatabase(JSON.parse(Bun.file(filePath).textSync()));
  } catch (error) {
    if (error instanceof Error && error.message === "Malformed database") throw error;
    fail("Malformed database");
