  }

  if (command === "done" || command === "delete") {
    if (args.length !== 2) fail(`Usage: ${command} ID`);
    const id = taskId(args[1]);
    const index = db.tasks.findIndex(task => task.id === id);
    if (index < 0) fail("Task not found");
    if (command === "delete") {
      db.tasks.splice(index, 1);
      await save(db);
      return { id, deleted: true };
    }
    const task = db.tasks[index];
    if (task.status === "open") {
      task.status = "done";
      task.completedAt = new Date().toISOString();
      await save(db);
    }
    return task;
  }

  if (command === "stats") {
    if (args.length !== 1) fail("Invalid option");
    const open = db.tasks.filter(task => task.status === "open");
    return { total: db.tasks.length, open: open.length, done: db.tasks.length - open.length, overdue: open.filter(task => task.due && task.due < localToday()).length };
  }
  fail(`Unknown command: ${command}`);
}

try {
  console.log(JSON.stringify(await main(process.argv.slice(2))));
} catch (error) {
  console.error(error instanceof Error ? error.message : "Unexpected error");
  process.exitCode = 1;
}
# Taskboard CLI

Dependency-free task manager for Bun. Each command prints one JSON value to stdout.

```sh
bun run src/cli.ts add --title "Ship release" --tags work,urgent --due 2026-09-10
bun run src/cli.ts list --status open --tag urgent
bun run src/cli.ts done 1
bun run src/cli.ts stats
bun run src/cli.ts delete 1
```

Tasks are stored in `.taskboard.json` in the current directory. Set `TASKBOARD_FILE` to use another location:

```sh
TASKBOARD_FILE=/tmp/tasks.json bun run src/cli.ts list
```

`list --overdue YYYY-MM-DD` returns open tasks due strictly before that date. Tags are trimmed, lower-cased, and deduplicated.
